#!/bin/bash
# Patch the compose env block's OPENAI_BASE_URL (host-network) + recreate + answer test
ssh -o BatchMode=yes -o ConnectTimeout=10 -i ~/.ssh/id_nura_clean root@72.61.71.211 'cd /docker/docsgpt/deployment && grep -n "OPENAI_BASE_URL\|ollama:11434" docker-compose.yaml | head -4 && sed -i "s|http://ollama:11434|http://127.0.0.1:11434|g" docker-compose.yaml && echo "=== after ===" && grep -n "OPENAI_BASE_URL" docker-compose.yaml | head -2 && docker compose -f docker-compose.yaml up -d --force-recreate backend 2>&1 | tail -1 && sleep 15 && docker exec docsgpt-oss-backend-1 sh -c "env | grep OPENAI_BASE_URL" 2>/dev/null | sed "s|://[^@]*@|://***@|" && K=$(grep "^API_KEY=" .env | head -1 | cut -d= -f2) && echo "=== answer ===" && curl -s -m 60 -X POST http://127.0.0.1:7091/api/answer -H "Content-Type: application/json" -d "{\"question\":\"What is anatomy?\",\"api_key\":\"$K\"}" 2>/dev/null | head -c 500'
